def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    green_sweater_patches = image_patch.find("green sweater")

    if not man_patches or not green_sweater_patches:
        return image_patch

    # Sort patches by their vertical center to find the man on top of the green sweater
    man_patches.sort(key=lambda p: p.vertical_center)
    green_sweater_patches.sort(key=lambda p: p.vertical_center)

    # Ensure the man is above the green sweater
    for man in man_patches:
        for sweater in green_sweater_patches:
            if man.overlaps_with(sweater.left, sweater.lower, sweater.right, man.lower):
                return man

    # If no clear overlap, return the man on top based on vertical center
    return man_patches[0]

