def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    apple_patches = image_patch.find("apple")
    banana_patches = image_patch.find("banana")

    if not apple_patches or not banana_patches:
        return image_patch

    # Filter apples that are under bananas
    under_bananas = []
    for apple in apple_patches:
        for banana in banana_patches:
            if apple.overlaps_with(apple.left, apple.lower, apple.right, banana.upper):
                under_bananas.append(apple)
                break

    # Filter apples with only red showing
    red_apples = [a for a in under_bananas if a.verify_property("apple", "red")]

    return red_apples[0] if red_apples else apple_patches[0]

